DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role; END IF; END $$;
CREATE TABLE profiles(id uuid PRIMARY KEY,is_horse boolean);
CREATE TABLE sp_daily_metrics(day date PRIMARY KEY,metrics jsonb);
CREATE TABLE ca_hand_facts(hand_id uuid,user_id uuid,played_at timestamptz,tournament_id uuid,club_id uuid,net numeric);
CREATE TABLE rake_attributions(hand_id uuid,player_id uuid,club_id uuid,rake_amount numeric,bbj_attributed_contribution numeric);
CREATE FUNCTION fn_diamond_arena_club() RETURNS uuid LANGUAGE sql AS $$ SELECT 'dddddddd-0000-0000-0000-000000000000'::uuid $$;
